function baseValidationIssues(m){if(m.modelType==='instances'){m={...m,components:model.components,dependencies:model.dependencies};delete m.modelType;}return window.builtinRuleEnabled?.()===false?[...A.inspectStructure(m),...A.inspectCompatibility(m)]:A.inspect(m);}
