function render(){if(directDiagram())mode='metamodel';renderSubgroupFilter(); $('#projectLabel').textContent=model.name;$('#metaCount').textContent=model.components.length;$('#instanceCount').textContent=model.instances.length;$('#canvasTitle').textContent=mode==='metamodel'?'Metamodel':'Instances';$('#canvasSubtitle').textContent=mode==='metamodel'?'Structure & dependencies':'Real systems & port connections';$('#counts').textContent=nodes().length+' building blocks   ·   '+edges().length+' connections';$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#connect').classList.toggle('active',connecting);$('#connect').setAttribute('aria-pressed',String(connecting));$('#canvas').classList.toggle('connecting',connecting);$('#canvasHint').textContent=connecting?(mode==='metamodel'?'Select source block, then target block':'Click two ports to connect · Click the active port to cancel'):'Drag blocks to arrange · Scroll to zoom';renderLibrary();renderGraph();renderInspector();renderValidation();renderModelingStyle();}
