function addComponent(){checkpoint();const id=uid('component');model.components.push({id,name:'New component',category:'',color:'#9b85cd',description:'',parentId:null,x:150+model.components.length*15,y:150+model.components.length*10,parameters:{},ports:[]});mode='metamodel';selected=id;selectedEdge=null;commit();fit();}
