async function addRelation(node,port){if(!pending){pending={node,port};renderGraph();toast(mode==='metamodel'?'Choose a target building block':'Choose a target data point');return;}let source=pending;pending=null;if(mode==='instances'){const first=model.instances.find(i=>i.id===source.node)?.ports.find(p=>p.id===source.port),second=model.instances.find(i=>i.id===node)?.ports.find(p=>p.id===port);if(first?.direction==='in'&&second?.direction==='out'){const initial=source;source={node,port};node=initial.node;port=initial.port;}}if(mode==='instances'&&source.node===node&&source.port===port){renderGraph();return;}if(mode==='metamodel'){checkpoint();model.dependencies.push({id:uid('dep'),source:source.node,target:node,label:'depends on'});commit();toast('Dependency created');return;}if(model.connections.some(c=>c.source.instanceId===source.node&&c.source.portId===source.port&&c.target.instanceId===node&&c.target.portId===port)){renderGraph();toast('These ports are already connected');return;}const connection={id:uid('connection'),source:{instanceId:source.node,portId:source.port},target:{instanceId:node,portId:port}},policy=A.connectionAllowed(model,connection.source,connection.target);if(!policy.allowed){renderGraph();toast(policy.message);return;}const baseline=JSON.stringify([model,window.ArchitexScripting?.listRules()]);renderGraph();const findings=await window.ArchitexScripting?.checkConnection(model,connection)||[];if(baseline!==JSON.stringify([model,window.ArchitexScripting?.listRules()]))return toast('Graph or rules changed. Try the connection again.');if(findings.length){toast(findings[0].message);return;}checkpoint();model.connections.push(connection);commit();toast('Connection created');}

