$('#graph').onpointerdown=e=>{if(e.button!==0&&e.button!==1)return;const port=e.target.closest('[data-port]'),node=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');if(connecting&&port&&mode==='instances'){e.preventDefault();addRelation(port.dataset.owner,port.dataset.port);return;}if(connecting&&node&&mode==='metamodel'){queueMetaRelation(node.dataset.node);return;}if(edge){selectedEdge=edge.dataset.edge;selected=null;render();return;}const n=node&&nodes().find(n=>n.id===node.dataset.node);if(n){selected=n.id;selectedEdge=null;checkpoint();renderLibrary();renderInspector();$$('#nodes .node').forEach(el=>el.classList.toggle('selected',el.dataset.node===selected));}else{selected=null;selectedEdge=null;renderInspector();$$('#nodes .node').forEach(el=>el.classList.remove('selected'));}drag={id:n?.id,startX:e.clientX,startY:e.clientY,x:n?box(n).x:view.x,y:n?box(n).y:view.y,offset:n&&visualParent(n)?{x:box(n).x-box(visualParent(n)).x,y:box(n).y-box(visualParent(n)).y}:null};(n?node:$('#graph')).setPointerCapture(e.pointerId);};
