function toMarkdown(m){return `# ${m.name}\n\nArchitex ${directDiagram()?'direct architecture diagram':mode}. Cyclic dependencies are allowed. ${directDiagram()?'Components connect directly; no metamodel or instances are required.':'Every instance port must be connected.'}\n\n## Components\n\n${m.components.map(c=>`### ${c.name}\n\n${c.description}\n\n- ID: ${c.id}\n- Category: ${c.category}\n- Color: ${c.color}\n- Subgroup of: ${c.parentId||'none'}\n- Default parameters: ${JSON.stringify(c.parameters)}\n\n${c.ports.map(p=>`- ${p.direction.toUpperCase()} port **${p.name}** (${p.id}): ${p.description}`).join('\n')}`).join('\n\n')}\n\n## Instances\n\n${m.instances.map(i=>`- **${i.name}** (${i.id}), component: ${i.componentId}; parameters: ${JSON.stringify(i.parameters)}`).join('\n')}\n\n## Dependencies\n\n${m.dependencies.map(d=>`- ${d.source} → ${d.target}: ${d.label}`).join('\n')}\n\n## Connections\n\n${m.connections.map(c=>`- ${c.source.instanceId}/${c.source.portId} → ${c.target.instanceId}/${c.target.portId}`).join('\n')}\n\n## Validation report\n\n${validationIssues(m).map(i=>'- '+i.severity.toUpperCase()+': '+i.message).join('\n')||'All checks passed.'}\n\n## Machine-readable model\n\nThe following block is authoritative for lossless re-import.\n\n\`\`\`architex-json\n${JSON.stringify(m,null,2)}\n\`\`\`\n`;}
