function nativeDrawio(doc){const diagrams=[...doc.querySelectorAll('diagram')];if(diagrams.length>1)throw Error('Import one draw.io page at a time. Export the desired page as uncompressed XML.');const graph=doc.querySelector('mxGraphModel');if(!graph)throw Error('Compressed draw.io files are not supported. In draw.io, export XML with compression disabled.');const m={version:1,name:'Imported diagram',components:[],dependencies:[],instances:[],connections:[]},map=new Map();const cells=[...graph.querySelectorAll('mxCell[vertex="1"]')];for(const [i,cell]of cells.entries()){const raw=cell.getAttribute('value')||'Component '+(i+1),label=new DOMParser().parseFromString(raw,'text/html').body.textContent,g=cell.querySelector('mxGeometry'),id=uid('component');map.set(cell.id,id);m.components.push({id,name:label||'Component',category:'',description:'Imported from draw.io',parentId:null,x:Number(g?.getAttribute('x')||0),y:Number(g?.getAttribute('y')||0),parameters:{},ports:[]});}for(const cell of cells){const parent=map.get(cell.getAttribute('parent'));if(parent){const n=m.components.find(n=>n.id===map.get(cell.id)),p=m.components.find(n=>n.id===parent);n.parentId=parent;n.x+=p.x;n.y+=p.y;}}for(const e of graph.querySelectorAll('mxCell[edge="1"]')){const s=map.get(e.getAttribute('source')),t=map.get(e.getAttribute('target'));if(s&&t)m.dependencies.push({id:uid('dep'),source:s,target:t,label:e.getAttribute('value')||'depends on'});}if(!m.components.length)throw Error('No editable vertices found in draw.io file');return m;}
