for(const n of ns){const cell=byId.get('node:'+n.id);if(!cell)continue;const g=cell.querySelector('mxGeometry');n.name=cell.getAttribute('value')||n.name;if(g){const x=Number(g.getAttribute('x')||0),y=Number(g.getAttribute('y')||0),parentId=isMeta&&cell.getAttribute('parent')?.startsWith('node:')?cell.getAttribute('parent').slice(5):null,parent=parentId&&original?.get(parentId),old=original?.get(n.id),expectedX=old?old.x-(parent?.x||0):n.x,expectedY=old?old.y-(parent?.y||0):n.y;if(isMeta){if(n.parentId!==parentId){n.parentId=parentId;delete n.subgroupPosition;}if(x!==expectedX||y!==expectedY){if(parentId)n.subgroupPosition={x,y};else{n.x=x;n.y=y;delete n.subgroupPosition;}}}else if(x!==expectedX||y!==expectedY){n.x=x;n.y=y;}}for(const p of n.ports){const pc=byId.get('port:'+n.id+':'+p.id);if(pc)p.name=pc.getAttribute('value')||p.name;}}
const endpoints=new Map();for(const n of ns){endpoints.set('node:'+n.id,n.id);for(const p of n.ports)endpoints.set('port:'+n.id+':'+p.id,{instanceId:n.id,portId:p.id});}
