const mermaidImportNotes=new WeakMap(),mermaidImportScopes=new WeakMap();
function importMermaid(text,type){const declared=ArchitexMermaid.parse(text).payload?.type,scope=type==='both'?'both':['metamodel','instances'].includes(declared)?declared:type;const incoming=validateImportedModel(ArchitexMermaid.fromMermaid(text,scope,model));mermaidImportNotes.set(incoming,[...ArchitexMermaid.lastWarnings]);if(scope==='instances'&&!incoming.modelType&&incoming.components.length)mermaidImportScopes.set(incoming,'both');return incoming;}
function parseImport(text,name,type=mode){const ext=name.split('.').pop().toLowerCase();let m;if(type==='both'&&ext==='rst')throw Error('For Both models, import a complete workspace JSON/YAML/XLSX or a Mermaid diagram. Import RST files separately by model.');if(ext==='rst')return validateImportedModel(ArchitexRST.parseProject([{path:name.split('/').at(-1),encoding:'utf8',content:text}],type,model));if(ext==='xlsx')throw Error('Use parseImportFile for binary Excel workbooks');if(ext==='mmd'||ext==='mermaid')return importMermaid(text,type);else if(ext==='puml'||ext==='plantuml')m=ArchitexExchange.fromPlantuml(text);else if(ext==='needs')m=ArchitexExchange.fromNeeds(JSON.parse(text));else if(ext==='json'){const data=JSON.parse(text);m=data.versions||data.needs?ArchitexExchange.fromNeeds(data):data;}else if(ext==='yaml'||ext==='yml')m=jsyaml.load(text,{schema:jsyaml.JSON_SCHEMA});else if(ext==='md'||ext==='markdown'){const block=text.match(/```architex-json\s*\n([\s\S]*?)\n```/);if(!block)return importMermaid(text,type);m=JSON.parse(block[1]);}else if(['svg','drawio','xml'].includes(ext)){const doc=xmlParse(text);if(doc.documentElement.localName==='svg'){const metadata=doc.querySelector('metadata#architex-model');if(!metadata)throw Error('This SVG has no Architex model metadata. Use an Architex SVG export for editable re-import.');m=JSON.parse(metadata.textContent);}else m=fromDrawio(doc);}else throw Error('Choose JSON, YAML, draw.io XML, SVG, Markdown, XLSX, Sphinx-Needs JSON, PlantUML, or Mermaid (.mmd/.mermaid).');return validateImportedModel(m);}
async function parseImportFile(file,type=mode){if(file.size>10*1024*1024)throw Error('File exceeds 10 MB limit');if(type==='both'&&file.name.toLowerCase().endsWith('.zip'))throw Error('Import RST projects separately by model, or use complete workspace JSON/YAML/XLSX for Both models.');if(file.name.toLowerCase().endsWith('.zip'))return validateImportedModel(ArchitexRST.parseProject(await ArchitexRST.readZip(await file.arrayBuffer()),type,model));if(file.name.toLowerCase().endsWith('.xlsx'))return validateImportedModel(await ArchitexExchange.fromXlsx(await file.arrayBuffer()));return parseImport(await file.text(),file.name,type);}
function applyImportedModel(incoming,type=mode,{clearInstances=false}={}){if(directDiagram()&&(incoming.instances?.length||incoming.connections?.length||incoming.modelType==='instances'))throw Error('This file contains typed instances. Switch to Metamodel and instances to import it; the direct diagram is unchanged.');const requested=type;type=mermaidImportScopes.get(incoming)||(['metamodel','instances'].includes(incoming.modelType)?incoming.modelType:type);const notes=[...(mermaidImportNotes.get(incoming)||[])];if(type!==requested)notes.push('Detected '+(type==='both'?'combined model':type==='instances'?'instance model':'metamodel')+' content and used the matching import scope.');const candidate=ArchitexScope.apply(model,incoming,type,{clearInstances:clearInstances&&requested==='metamodel'&&type==='metamodel'});checkpoint();model=candidate;mode=type==='both'?'instances':type;$('#exchangeModel').value=type;selected=null;selectedEdge=null;pending=null;commit();fit();$('#ioDialog').close();$('#importNotes').hidden=!notes.length;$('#importNoteList').replaceChildren();for(const note of notes){const item=document.createElement('li');item.textContent=note;$('#importNoteList').append(item);}$('#importNoteSummary').textContent='Import notes ('+notes.length+')';toast((directDiagram()?'Architecture diagram':type==='both'?'Both models':type==='metamodel'?'Metamodel':'Instance model')+' imported successfully');}

let ioMode='export';
function updateExchangeDialog(){for(const option of $('#exchangeModel').options){if(!option.dataset.originalLabel)option.dataset.originalLabel=option.textContent;option.hidden=directDiagram()&&option.value!=='metamodel';option.disabled=directDiagram()&&option.value!=='metamodel';option.textContent=directDiagram()&&option.value==='metamodel'?'Architecture diagram':option.dataset.originalLabel;}const type=$('#exchangeModel').value;if(type!=='metamodel')$('#clearInstances').checked=false;$('#bothModelsOption').hidden=ioMode!=='import';$('#bothModelsOption').disabled=ioMode!=='import';$('#ioTitle').textContent=(ioMode==='export'?'Export ':'Import ')+(type==='both'?'both models':type==='metamodel'?'metamodel':'instance model');$('#ioHelp').textContent=ioMode==='export'?(type==='metamodel'?'Export component definitions, ports, defaults, and dependencies. Instances are excluded.':'Export only instances, parameter values, and port connections. Import these against the matching metamodel.'):(type==='both'?'Replace the complete metamodel and instance model together. A plain Mermaid diagram generates component definitions, one instance per component and connected directional data points. This replaces both existing models and can be undone.':type==='metamodel'?'Replace the metamodel while retaining compatible instances. Select the clear option only if you want to discard the existing instance model.':'Replace only instances and port connections. The active metamodel and its definitions are kept.');$('#exportAllComponentPorts').hidden=ioMode!=='export'||type!=='metamodel';$('#clearInstancesLabel').hidden=ioMode!=='import'||type!=='metamodel';$('#folderLabel').hidden=ioMode!=='import'||type==='both';$('#ioError').textContent='';if(directDiagram()){$('#exchangeModel').value='metamodel';$('#bothModelsOption').hidden=true;$('#bothModelsOption').disabled=true;$('#clearInstancesLabel').hidden=true;$('#ioTitle').textContent=(ioMode==='export'?'Export ':'Import ')+'architecture diagram';$('#ioHelp').textContent='Direct components and connections. No type definitions or instances are required. Graph interchange uses the existing component/dependency schema.';}}
function openIO(type){ioMode=type;$('#exchangeModel').value=mode;$('#clearInstances').checked=false;$('#fileLabel').hidden=type==='export';$('#folderLabel').hidden=type==='export';$('#doExport').hidden=type==='import';$('#format').parentElement.hidden=type==='import';$('#file').value='';$('#rstFolder').value='';updateExchangeDialog();$('#ioDialog').showModal();}
$('#exchangeModel').onchange=()=>{if($('#exchangeModel').value!=='both')setMode($('#exchangeModel').value);updateExchangeDialog();};
$('#import').onclick=()=>openIO('import');$('#export').onclick=()=>openIO('export');
$('#doExport').onclick=async()=>{try{await window.ensureScriptValidation?.(model);const format=$('#format').value;download('architex-'+(directDiagram()?'diagram':mode)+(format==='needs'?'.needs.json':format==='rst'?'-sphinx-rst.zip':'.'+format),await exportFile(format),format==='rst'?'application/zip':format==='svg'?'image/svg+xml':format==='json'||format==='needs'?'application/json':format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':format==='drawio'?'application/xml':'text/plain');toast('Export downloaded');}catch(e){$('#ioError').textContent=e.message;}};
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const importType=$('#exchangeModel').value,clearInstances=$('#clearInstances').checked;try{applyImportedModel(await parseImportFile(file,importType),importType,{clearInstances});}catch(err){$('#ioError').textContent=err.message;}};
$('#rstFolder').onchange=async e=>{const importType=$('#exchangeModel').value,clearInstances=$('#clearInstances').checked;try{const incoming=ArchitexRST.parseProject(await ArchitexRST.readFolder(e.target.files),importType,model);applyImportedModel(incoming,importType,{clearInstances});}catch(err){$('#ioError').textContent=err.message;}};

function schemas(){try{download('architex-schema-catalog.json',JSON.stringify(ArchitexHandover.bundledSchemas(),null,2),'application/json');toast('Downloaded all model, rule, relay, proposal and interchange schemas');}catch(e){toast(e.message);}}
$('#schemas').onclick=schemas;$('#schemaRail').onclick=schemas;
async function exportValidationReport(format){const button=$(format==='xlsx'?'#downloadReportXlsx':'#downloadReport');button.disabled=true;try{const snapshot=A.clone(model),library=A.clone(window.ArchitexScripting?.exportLibrary()||{defaultRuleEnabled:true,rules:[]}),checkedAt=new Date().toISOString(),rules=[{...A.clone(ArchitexValidation.defaultRule),enabled:library.defaultRuleEnabled},...library.rules],custom=await window.ArchitexScripting?.checkCandidate(snapshot,library)||[],core=library.defaultRuleEnabled?A.inspect(snapshot):[...A.inspectStructure(snapshot),...A.inspectCompatibility(snapshot)],report={model:snapshot.name,checkedAt,rules,issues:[...core,...custom]};if(format==='xlsx')download('architex-validation.xlsx',await ArchitexExchange.toValidationXlsx(report,snapshot),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');else download('architex-validation.json',JSON.stringify(report,null,2),'application/json');toast('Validation report exported.');}catch(e){toast('Could not export validation report: '+e.message);}finally{button.disabled=false;}}
$('#downloadReport').onclick=()=>exportValidationReport('json');$('#downloadReportXlsx').onclick=()=>exportValidationReport('xlsx');
window.ArchitexIO={exportFile,parseImport,parseImportFile,applyImportedModel,getModel:()=>A.clone(model),getMode:()=>mode};
function renderModelingStyle(){const direct=directDiagram();$('#modelingStyle').value=modelingStyle;const meta=$('[data-mode="metamodel"]'),instances=$('[data-mode="instances"]');meta.firstChild.textContent=direct?'◇ Architecture diagram ':'◇ Metamodel ';instances.hidden=direct;$('#clearModels').textContent=direct?'Clear diagram':'Clear models';$('#clearModels').title=direct?'Clear this direct architecture diagram':'Clear the metamodel and instance model';$('#metamodelDescription').textContent=direct?'↧ Diagram description':'↧ Metamodel description';if(!direct)return;$('#canvasTitle').textContent='Architecture diagram';$('#canvasSubtitle').textContent='Components & directed connections · no metamodel required';$('#instanceFilterBar').hidden=true;$('#instantiate')?.setAttribute('hidden','');for(const field of $$('[data-allowed-components],[data-port-exposure]'))field.closest('label').hidden=true;for(const section of $$('#inspector .section-label'))section.firstChild.textContent=section.textContent.includes('PARAMETERS')?'PARAMETERS ':'INTERFACE PORTS ';const type=$('#inspector .inspect-type');if(type&&selected)type.textContent='Diagram component';$('#libraryContents .panel-name')?.replaceChildren(document.createTextNode('COMPONENTS'));if(!validationIssues(model).length)$('#issues').innerHTML='<div class="issue"><span class="ok">✓</span><strong>Diagram structure is valid.</strong><span>No metamodel or instances required. Connect components directly.</span></div>';}
function setModelingStyle(next){if(!['typed','diagram'].includes(next))return;if(next===modelingStyle)return;if(window.SuiteWorkspaceAdapter?.isBusy?.()||window.SuiteCodingAgent?.running?.()||$('#layout').disabled){$('#modelingStyle').value=modelingStyle;return toast('Finish the active operation before switching modeling mode.');}try{const nextKey=next==='diagram'?'architex-direct-v1':'architex-v1',saved=localStorage.getItem(nextKey),candidate=A.validate(saved?JSON.parse(saved):next==='diagram'?emptyDiagram():A.clone(A.demo));if(next==='diagram'&&(candidate.instances.length||candidate.connections.length))throw Error('The saved direct diagram contains typed instances.');if(!save()){$('#modelingStyle').value=modelingStyle;return;}localStorage.setItem('architex-modeling-style',next);workspaceHistories.set(modelingStyle,{history,future});cancelMetaRelations();modelingStyle=next;model=candidate;history=workspaceHistories.get(next)?.history||[];future=workspaceHistories.get(next)?.future||[];mode='metamodel';selected=null;selectedEdge=null;instanceSubgroup='';pending=null;connecting=false;drag=null;$('#importNotes').hidden=true;commit();fit();toast(next==='diagram'?'Direct diagram ready. Add components and connect them directly.':'Metamodel and instances restored.');}catch(error){$('#modelingStyle').value=modelingStyle;toast('Could not switch modeling mode: '+error.message);}}
$('#modelingStyle').onchange=e=>setModelingStyle(e.target.value);
render();requestAnimationFrame(fit);
// Keep the whole architecture visible when the workspace changes size.
let resizeFrame;
new ResizeObserver(()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(fit);}).observe($('#canvas'));

$('#metamodelDescription').onclick=async()=>{try{if(directDiagram()){download('architex-diagram-description.json',JSON.stringify({format:'architex-direct-diagram-description',version:1,name:model.name,description:'Direct architecture components and directed connections. No metamodel or instances are required. Components support containment, parameters, presentation and descriptive interface ports.',nodes:A.clone(model.components),connections:A.clone(model.dependencies)},null,2),'application/json');return toast('Diagram description downloaded');}const catalog=ArchitexHandover.bundledSchemas();const document={format:'architex-configured-metamodel-description',version:1,name:model.name,description:'Configured component types, subgroup hierarchy, parameter defaults, dependency graph and connection policies. Instance data points reference these policies with definitionId; both endpoint policies must allow the peer component type. Empty allowedComponentIds permits no peers.',metamodel:{components:A.clone(model.components),dependencies:A.clone(model.dependencies)},schemas:{metamodel:catalog.schemas.metamodel,componentConnectionPolicy:catalog.schemas.componentConnectionPolicy,instanceDataPoint:catalog.schemas.instanceDataPoint}};download('architex-configured-metamodel.json',JSON.stringify(document,null,2),'application/json');toast('Configured metamodel description downloaded');}catch(e){toast(e.message);}};

function foldProjectIntro(collapsed){$('#projectIntro').hidden=collapsed;$('.project-heading').classList.toggle('intro-collapsed',collapsed);$('#toggleProjectHeading').setAttribute('aria-expanded',String(!collapsed));$('#toggleProjectHeading').textContent=collapsed?'▸ Show introduction':'▾ Hide introduction';}
try{foldProjectIntro(localStorage.getItem('architex-intro-collapsed')==='true');}catch{}
$('#toggleProjectHeading').onclick=()=>{const collapsed=!$('#projectIntro').hidden;foldProjectIntro(collapsed);try{localStorage.setItem('architex-intro-collapsed',String(collapsed));}catch{}};

function foldWorkspaceHeader(collapsed){$('#workspaceHeader').hidden=collapsed;$('#toggleWorkspaceHeader').setAttribute('aria-expanded',String(!collapsed));$('#toggleWorkspaceHeader').setAttribute('aria-label',collapsed?'Show workspace header':'Hide workspace header');$('#toggleWorkspaceHeader').title=collapsed?'Show header':'Hide header';$('#toggleWorkspaceHeader').textContent=collapsed?'▾ Show header':'▴ Hide header';}
try{foldWorkspaceHeader(localStorage.getItem('architex-header-collapsed')==='true');}catch{}
$('#toggleWorkspaceHeader').onclick=()=>{const collapsed=!$('#workspaceHeader').hidden;foldWorkspaceHeader(collapsed);try{localStorage.setItem('architex-header-collapsed',String(collapsed));}catch{}};

$('#clearModels').onclick=()=>{cancelMetaRelations();if(!model.components.length&&!model.dependencies.length&&!model.instances.length&&!model.connections.length&&!model.sphinx)return toast(directDiagram()?'The diagram is already empty.':'Both models are already empty.');if(!confirm(directDiagram()?'Clear this architecture diagram, including all components, connections and retained source files? You can undo this with Ctrl/Command Z.':'Clear the entire metamodel and instance model, including all dependencies, connections and retained Sphinx source files? You can undo this with Ctrl/Command Z.'))return;checkpoint();model.components=[];model.dependencies=[];model.instances=[];model.connections=[];delete model.sphinx;selected=null;selectedEdge=null;pending=null;connecting=false;drag=null;mode='metamodel';commit();fit();toast(directDiagram()?'Diagram cleared. Undo with Ctrl/Command Z.':'Both models cleared. Undo with Ctrl/Command Z.');};

$('#instanceSubgroup').onchange=e=>{instanceSubgroup=e.target.value;selected=null;selectedEdge=null;pending=null;drag=null;render();fit();};

async function loadComponentIcon(file){if(file.size>512*1024)throw Error('Choose an icon no larger than 512 KB.');if(!['image/png','image/jpeg','image/webp','image/svg+xml'].includes(file.type)&&!/^.+\.(png|jpe?g|webp|svg)$/i.test(file.name))throw Error('Choose a PNG, JPEG, WebP or SVG image.');const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Icon image took too long to load.')),10000);image.onload=()=>{clearTimeout(timer);resolve();};image.onerror=()=>{clearTimeout(timer);reject(Error('This file could not be read as an image.'));};image.src=url;});if(!image.naturalWidth||!image.naturalHeight)throw Error('The image has no usable dimensions.');const canvas=document.createElement('canvas');const raster=size=>{canvas.width=canvas.height=size;const scale=Math.min(size/image.naturalWidth,size/image.naturalHeight),w=image.naturalWidth*scale,h=image.naturalHeight*scale;canvas.getContext('2d').drawImage(image,(size-w)/2,(size-h)/2,w,h);return canvas.toDataURL('image/png');};let icon=raster(96);if(icon.length>32767)icon=raster(64);A.checkSchema(icon,A.schema.properties.components.items.properties.icon);return icon;}finally{URL.revokeObjectURL(url);}}
$('#inspector').addEventListener('change',async e=>{if(e.target.id!=='componentIcon'||mode!=='metamodel')return;const file=e.target.files[0],id=selected,n=model.components.find(c=>c.id===id);if(!file||!n)return;const baseline=JSON.stringify(n);try{const icon=await loadComponentIcon(file),current=model.components.find(c=>c.id===id);if(!current||JSON.stringify(current)!==baseline)throw Error('The component changed while loading the icon. Please choose the icon again.');checkpoint();current.icon=icon;commit();toast('Component icon loaded. Instances use the same icon.');}catch(err){e.target.value='';toast(err.message);}});

async function exportComponentPorts(ids=null){try{const snapshot=A.clone(model),buffer=await ArchitexExchange.toPortsXlsx(snapshot,ids),suffix=ids?.length===1?'-'+ids[0].replace(/[^a-zA-Z0-9_-]/g,'_'):'';download('architex-component-ports'+suffix+'.xlsx',buffer,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Component ports exported to Excel.');}catch(e){toast(e.message);if($('#ioDialog').open)$('#ioError').textContent=e.message;}}
$('#exportAllComponentPorts').onclick=()=>exportComponentPorts();

let metaRelationTimers=new Set();
function cancelMetaRelations(){for(const timer of metaRelationTimers)clearTimeout(timer);metaRelationTimers.clear();}
function queueMetaRelation(id){const timer=setTimeout(()=>{metaRelationTimers.delete(timer);if(mode==='metamodel'&&connecting&&model.components.some(n=>n.id===id))addRelation(id);},500);metaRelationTimers.add(timer);}
function detailsTable(headers,rows){return rows.length?`<div class="details-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(value=>`<td>${esc(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="details-empty">None</p>';}
function showComponentDetails(id){const instance=mode==='instances'?model.instances.find(n=>n.id===id):null,c=model.components.find(c=>c.id===(instance?.componentId||id));if(!c)return;const n=instance||c,effective=A.effectivePorts(model,c.id),componentName=id=>model.components.find(c=>c.id===id)?.name||id,instanceName=id=>model.instances.find(i=>i.id===id)?.name||id,children=model.components.filter(t=>{let p=t,seen=new Set;while(p.parentId&&!seen.has(p.id)){seen.add(p.id);if(p.parentId===c.id)return true;p=model.components.find(parent=>parent.id===p.parentId)||{id:'',parentId:null};}return false;}),typeIds=new Set([c.id,...children.map(t=>t.id)]),instances=model.instances.filter(i=>typeIds.has(i.componentId)),relatedIds=new Set([...typeIds,...instances.map(i=>i.id)]),issues=validationIssues(model).filter(i=>instance?i.nodeId===instance.id:relatedIds.has(i.nodeId));const metaPorts=effective.map(p=>[p.name,p.id,p.direction,p.description,p.inherited?'Exposed from '+componentName(p.sourceComponentId):'Owned',p.exposedToParent!==false?'Yes':'No',p.allowedComponentIds.map(componentName).join(', ')]),points=instance?.ports.map(p=>[p.name,p.id,p.direction,p.description,effective.find(d=>d.id===p.definitionId)?.name||p.definitionId,model.connections.filter(e=>[e.source,e.target].some(ep=>ep.instanceId===instance.id&&ep.portId===p.id)).map(e=>e.id).join(', ')])||[],deps=model.dependencies.filter(d=>typeIds.has(d.source)||typeIds.has(d.target)),links=instance?model.connections.filter(e=>e.source.instanceId===instance.id||e.target.instanceId===instance.id):model.connections.filter(e=>instances.some(i=>[e.source.instanceId,e.target.instanceId].includes(i.id)));$('#componentDetailsTitle').textContent=n.name;$('#componentDetailsBody').innerHTML=`<p>${instance?'Instance of '+esc(c.name):directDiagram()?'Diagram component':'Metamodel component'} · <code>${esc(n.id)}</code></p>${c.icon?`<img class="details-icon" src="${esc(c.icon)}" alt="">`:''}<h3>Description</h3><p class="details-description">${esc(c.description||'No description')}</p>${detailsTable(['Property','Value'],[['Component ID',c.id],['Category',c.category||'None'],['Color',c.color],['Subgroup of',c.parentId?componentName(c.parentId):'Top level']])}<h3>${instance?'Instance parameters':'Default parameters'}</h3>${detailsTable(['Key','Value'],Object.entries(n.parameters))}${instance?`<h3>Data-point ports</h3>${detailsTable(['Name','ID','Direction','Description','Policy','Connections'],points)}`:''}<h3>Component interface — owned and exposed ports</h3>${detailsTable(['Name','ID','Direction','Description','Source','Expose on parent','Allowed types'],metaPorts)}<h3>Subgroups — all levels</h3>${detailsTable(['Name','ID','Parent'],children.map(t=>[t.name,t.id,componentName(t.parentId)]))}<h3>Instances in this component branch</h3>${detailsTable(['Name','ID','Parameters'],instances.map(i=>[i.name,i.id,JSON.stringify(i.parameters)]))}<h3>Component dependencies</h3>${detailsTable(['From','To','Relationship','ID'],deps.map(d=>[componentName(d.source),componentName(d.target),d.label,d.id]))}<h3>Instance connections</h3>${detailsTable(['ID','Source instance','Source port','Target instance','Target port'],links.map(e=>[e.id,instanceName(e.source.instanceId),e.source.portId,instanceName(e.target.instanceId),e.target.portId]))}<h3>Validation findings</h3>${detailsTable(['Severity','Rule','Message'],issues.map(i=>[i.severity,i.ruleName||'Model integrity',i.message]))}<details><summary>Complete related data (JSON)</summary><pre>${esc(JSON.stringify({component:c,...(instance?{instance}:{}),effectivePorts:effective,subgroups:children,instances,dependencies:deps,connections:links,validation:issues},null,2))}</pre></details>`;$('#componentDetailsDialog').showModal();}
$('#graph').ondblclick=e=>{const node=e.target.closest('[data-node]');if(!node)return;e.preventDefault();cancelMetaRelations();pending=null;drag=null;showComponentDetails(node.dataset.node);};
$('#closeComponentDetails').onclick=()=>$('#componentDetailsDialog').close();

